const range=(k,label,min,max,step=1,unit='')=>`<label>${label} <output data-output="${k}"></output><input data-setting="${k}" type="range" min="${min}" max="${max}" step="${step}" data-unit="${unit}"></label>`;
const effects=['rgb','glitch','mirror','wave','mono','invert','mosaic','strobe','zoom','film'];
const fxControls=()=>`<section class="mosw"><h3>MOSW FX</h3><p>ENABLE UP TO 3 · DRAG TO REORDER</p><div id="fxList">${effects.map(name=>{const value=name==='mosaic'?12:35;return `<div class="fx-row" draggable="true" data-fx="${name}"><span class="handle">⋮⋮</span><label class="check"><input type="checkbox" data-fx-toggle="${name}"> ${name.toUpperCase()}</label><input aria-label="${name} amount" type="range" min="1" max="100" value="${value}" data-fx-param="${name}"><output data-fx-output="${name}">${value}</output></div>`}).join('')}</div><label>SYNC SOURCE<select id="syncSource"><option value="manual">MANUAL BPM</option><option value="mic">MIC INPUT</option></select></label>${range('bpm','BPM',40,240,1)}<p id="bpmStatus">SYNC: MANUAL</p></section>`;
const color=(k,label)=>`<label>${label}<input data-setting="${k}" type="color"></label>`;
export function buildUI(){return `<main><section id="studio"><header><strong>HAND MOTION / <span id="status">STANDBY</span></strong><div><button id="startCamera">START CAMERA</button><button id="flip">CAMERA</button><button id="fullscreen">FULL</button><button id="shot">SHOT</button><button id="record">REC</button></div></header><div class="layout"><aside class="modes"><p>MODE SELECT</p>${[['cube','Hand Cube AR'],['invisible','Invisible 2.0'],['dissolve','Particle Dissolve'],['frame','Hand Frame / 8-bit'],['volume','Hand Volume'],['anime','Anime Frame']].map(([v,n])=>`<button data-mode="${v}">${n}</button>`).join('')}</aside><section id="stage"><video id="camera" playsinline muted></video><canvas id="output"></canvas><canvas id="three"></canvas><canvas id="overlay"></canvas><div class="hint"><b id="gestureStatus">GESTURE: UNKNOWN</b><br/><span id="maskStatus">PERSON MASK: NOT READY</span><br/>INVISIBLE: controlled by OPEN / FIST</div></section><aside class="controls"><p>PARAMETERS</p><div data-mode-panel="cube">${range('size','CUBE SIZE',.4,2,.1)}${range('speed','ROTATION',.1,3,.1)}${color('cubeColor','CUBE COLOR')}</div><div data-mode-panel="invisible" hidden><p id="backgroundStatus">BACKGROUND: NOT CAPTURED</p><button id="capture">CAPTURE BACKGROUND</button><button id="clearBackground">CLEAR BACKGROUND</button><button id="maskDebug">MASK DEBUG: OFF</button>${range('gestureHold','GESTURE HOLD',200,1200,50,'ms')}${range('transitionDuration','TRANSITION',200,2000,50,'ms')}${range('edgeGlow','EDGE GLOW',0,30,1)}</div><div data-mode-panel="dissolve" hidden>${range('particles','PARTICLE COUNT',50,1200,50)}${range('particleSize','PARTICLE SIZE',1,12,1)}${range('speed','PARTICLE SPEED',.1,3,.1)}${range('dispersion','DISPERSION',10,180,5)}${range('transitionDuration','TRANSITION',200,2000,50,'ms')}${color('particleColor','PARTICLE COLOR')}</div><div data-mode-panel="frame" hidden><label>PRESET<select data-setting="frameEffect"><option value="pop">NEON POP</option><option value="cmyk">CMYK</option><option value="mono">MONOCHROME</option><option value="pixel">CLASSIC PIXEL</option></select></label>${range('pixelSize','PIXEL SIZE',2,32,1)}${fxControls()}</div><div data-mode-panel="volume" hidden>${range('size','VOLUME SCALE',.4,2,.1)}${color('edgeColor','EDGE COLOR')}</div><div data-mode-panel="anime" hidden>${range('posterize','COLOR LEVELS',2,10,1)}</div><hr/><label class="check"><input data-setting="debug" type="checkbox"> LANDMARK DEBUG</label><label class="check"><input data-setting="mirror" type="checkbox"> MIRROR VIDEO</label><button id="reset">RESET SETTINGS</button><button id="export">EXPORT JSON</button><button id="import">IMPORT JSON</button><input id="importFile" type="file" accept="application/json" hidden/></aside></div><footer id="metrics">Camera FPS: 0 · Render FPS: 0 · MediaPipe FPS: 0</footer></section></main>`}
